            :class="[
              activeArtifactId === tool.callId
                ? 'bg-[#1764e8] text-white'
                : tool.status === 'success'
                  ? 'bg-[#f0eeea] dark:bg-[#26231f] text-[#1c1a17] dark:text-[#faf9f7] group-hover:bg-[#edf4ff] group-hover:text-[#1764e8]'
                  : 'bg-[#f0eeea] text-[#746f66]'
