        :is-running="isGenerating"
        @select-session="handleSelectSession"
        @new-session="handleNewSession"
        @rename-session="handleRenameSession"
        @delete-session="handleDeleteSession"
        @open-settings="ui.弹出提示('设置面板与工具链就绪', 'info')"
      />
    </div>
