            <span>工坊主页</span>
          </button>
          <!-- 会话侧边栏显隐切换 -->
          <button
            type="button"
            @click="showSessionSidebar = !showSessionSidebar"
            class="w-7 h-7 rounded-lg border border-[#e4e1da] dark:border-[#33302a] text-[#746f66] hover:text-[#1c1a17] hover:bg-[#f0eeea] flex items-center justify-center cursor-pointer transition-colors"
            :title="showSessionSidebar ? '收起会话列表' : '展开会话列表'"
          >
            <PanelLeftClose v-if="showSessionSidebar" :size="13" />
            <PanelLeftOpen v-else :size="13" />
          </button>
          <span class="font-bold text-xs text-[#1c1a17] dark:text-[#faf9f7] truncate font-mono">
            {{ currentSessionTitle }}
          </span>
          <span class="px-2 py-0.5 rounded-full bg-[#edf4ff] dark:bg-[#1e293b] border border-[#cce0ff] dark:border-[#3b82f6]/40 text-[10px] text-[#1764e8] dark:text-[#60a5fa] font-mono font-semibold flex items-center gap-1">
            <span class="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
            <span>端侧 12GB 独显就绪</span>
          </span>
        </div>
        <div class="flex items-center gap-2.5 shrink-0">
          <span class="text-[11px] font-mono text-[#746f66] dark:text-[#8f8a81]">
            297k Token
          </span>
          <!-- 画布开关 -->
          <button
            type="button"
            @click="showArtifactDrawer = !showArtifactDrawer"
            class="h-7 px-2.5 rounded-lg border text-xs font-mono font-bold flex items-center gap-1.5 transition-all cursor-pointer"
            :class="[
              showArtifactDrawer
                ? 'bg-[#1c1a17] dark:bg-[#faf9f7] text-white dark:text-[#1c1a17] border-transparent shadow-xs'
                : 'bg-white dark:bg-[#26231f] border-[#e4e1da] dark:border-[#33302a] text-[#746f66] hover:text-[#1c1a17]'
            ]"
          >
            <Layers :size="12" />
            <span>{{ showArtifactDrawer ? '画布开启' : '画布折叠' }}</span>
            <span v-if="allArtifacts.length > 0" class="px-1.5 py-0.2 rounded-full bg-emerald-500/20 text-emerald-600 text-[9.5px]">
              {{ allArtifacts.length }}
            </span>
          </button>
        </div>
      </header>
      <!-- 消息流主视窗滚动区 -->
      <main
        ref="scrollContainerRef"
        @scroll="updateScrollPresence"
        @wheel="handleWheel"
        class="flex-1 overflow-y-auto p-4 sm:p-6 space-y-6 custom-scrollbar z-10"
      >
        <div class="max-w-[760px] w-full mx-auto space-y-6">
          <MessageItem
            v-for="msg in messages"
            :key="msg.id"
            :message="msg"
            :is-generating="isGenerating"
            :active-artifact-id="activeArtifactId"
            :live-tokens-per-sec="currentTokensPerSec"
            @select-artifact="(callId) => { selectArtifact(callId); showArtifactDrawer = true; }"
            @toggle-thinking="(msgId) => toggleThinking(msgId)"
          />
          <!-- 贴底定位锚点 -->
          <div ref="liveContentEndRef" class="h-1 w-full" />
        </div>
      </main>
      <!-- 悬浮磁吸贴底快捷按钮 -->
      <button
        v-if="isAwayFromBottom"
        type="button"
        @click="reattachAutoFollow"
        class="absolute bottom-24 right-8 h-8 px-3 rounded-full bg-white dark:bg-[#1c1a17] border border-[#e4e1da] dark:border-[#33302a] text-[#1764e8] text-xs font-mono font-bold flex items-center gap-1.5 shadow-md hover:scale-105 transition-all cursor-pointer z-20"
        title="跳转至最新输出流"
      >
        <ArrowDown :size="12" />
        <span>回到底部</span>
      </button>
      <!-- 底部悬浮式白底 Composer 输入底座 (760px 居中对齐) -->
      <footer class="p-4 pt-1 z-20 shrink-0">
        <div class="max-w-[760px] w-full mx-auto">
          <ChatComposer
            v-model="inputPrompt"
            :is-generating="isGenerating"
            model-name="Qwen3-8B Local"
            :thinking-enabled="thinkingEnabled"
            :tool-preset="currentToolPreset"
            @send="handleSend"
            @abort="abortCurrentTask"
            @toggle-thinking="thinkingEnabled = !thinkingEnabled"
            @toggle-model="ui.弹出提示('已锁定专属 8B GGUF 离线大模型', 'info')"
            @compact="clearSession"
          />
        </div>
      </footer>
    </div>
    <!-- ==================== 3. 最右栏：全功能 Tab 产物/文件画布 ==================== -->
    <div
      v-if="showArtifactDrawer"
      class="h-full overflow-hidden transition-all duration-300 ease-in-out border-l border-[#e4e1da] dark:border-[#33302a] flex-shrink-0"
      :class="isArtifactMaximized ? 'w-full' : 'w-[480px] lg:w-[540px] xl:w-[600px]'"
    >
      <ArtifactCanvas
        :current-artifact="currentArtifact"
        :all-artifacts="allArtifacts"
        :is-maximized="isArtifactMaximized"
        @select-artifact="(callId) => selectArtifact(callId)"
        @toggle-maximize="isArtifactMaximized = !isArtifactMaximized"
        @close="showArtifactDrawer = false"
      />
    </div>
  </div>
</template>// 🛡️ service-asr MOSS 语音大模型转写专属处理器 (handlers/audio.rs)
use serde_json::{json, Value};
use service_asr::{AsrOptions, AsrService};
use shared_contracts::{TaskWeight, VramTokenGuard};
use std::path::Path;
use std::sync::Arc;
pub async fn handle(
    _tool_name: &str,
    params: Value,
    vram_guard: Arc<VramTokenGuard>,
) -> Result<Value, String> {
    let audio_path_str = params.get("audio_path").and_then(Value::as_str).ok_or("缺少 audio_path 参数")?;
    let audio_p = Path::new(audio_path_str);
    if !audio_p.exists() {
        return Err(format!("音频/视频物理文件不存在: {audio_path_str}"));
    }
    let language = params.get("language").and_then(Value::as_str).map(str::to_string);
    let prompt = params.get("prompt").and_then(Value::as_str).map(str::to_string);
    let hotwords = params.get("hotwords").and_then(Value::as_str).map(str::to_string);
    let temperature = params.get("temperature").and_then(Value::as_f64).map(|v| v as f32);
    let options = AsrOptions {
        audio_path: audio_path_str.to_string(),
        language,
        prompt,
        hotwords,
        max_new_tokens: None,
        temperature,
    };
    let _permit = vram_guard.acquire(TaskWeight::Heavy).await?;
    let asr_res = AsrService::run_asr_pipeline_cancellable(options, None, None).await
        .map_err(|e| format!("MOSS 语音大模型转写推导失败: {e}"))?;
    let full_transcript = asr_res.segments.iter()
        .map(|s| format!("[{} {:.1}s~{:.1}s]: {}", s.speaker, s.start_sec, s.end_sec, s.text))
        .collect::<Vec<_>>()
        .join("\n");
    Ok(json!({
        "audio_file": asr_res.audio_file,
        "duration_sec": asr_res.duration_sec,
        "total_segments": asr_res.segments.len(),
        "full_transcript": full_transcript,
        "segments": asr_res.segments,
        "elapsed_ms": asr_res.elapsed_ms
    }))
}// 🛡️ service-converter 全能格式转换与解密专属处理器 (handlers/converter.rs)
use format_converter::{service::FormatConvertService, FormatConvertTask};
use serde_json::{json, Value};
use shared_contracts::VramTokenGuard;
use std::path::Path;
use std::sync::Arc;
pub async fn handle(
    _tool_name: &str,
    params: Value,
    _vram_guard: Arc<VramTokenGuard>,
) -> Result<Value, String> {
    let input_path_str = params.get("input_path").and_then(Value::as_str).ok_or("缺少 input_path 参数")?;
    let in_p = Path::new(input_path_str);
    if !in_p.exists() {
        return Err(format!("待转换源文件不存在: {input_path_str}"));
    }
    let target_format = params.get("target_format").and_then(Value::as_str).ok_or("缺少 target_format 参数")?.to_string();
    let output_dir = params.get("output_dir").and_then(Value::as_str).map(str::to_string);
    let task = FormatConvertTask {
        input_path: input_path_str.to_string(),
        target_format,
        output_dir,
    };
    tokio::task::spawn_blocking(move || {
        let res = FormatConvertService::convert(&task);
        Ok(json!({
            "success": res.success,
            "input_path": res.input_path,
            "output_path": res.output_path,
            "detected_format": res.detected_format,
            "message": res.message
        }))
    })
    .await
    .map_err(|e| format!("Tokio 线程调度异常: {e}"))?
}// 🛡️ service-doc-parse 多模态文档与图像通用深度重构总成 (handlers/doc.rs)
// 100% 串联 5 大纯血底座：PP-DocLayoutV3 + SLANet + PP-FormulaNet + PP-OCRv6 + XY-Cut 空间编织
use pdf_parse::service::PdfParseService;
use serde_json::{json, Value};
use service_doc_parse::DocParseEngine;
use shared_contracts::{TaskWeight, VramTokenGuard};
use std::path::PathBuf;
use std::sync::Arc;
use std::time::Instant;
pub async fn handle(
    _tool_name: &str,
    params: Value,
    vram_guard: Arc<VramTokenGuard>,
) -> Result<Value, String> {
    let file_path_str = params.get("file_path").and_then(Value::as_str).ok_or("缺少 file_path 参数")?;
    let in_p = PathBuf::from(file_path_str);
    if !in_p.exists() {
        return Err(format!("待解析物理文件不存在: {file_path_str}"));
    }
    let target_out_dir = if let Some(out_dir_str) = params.get("output_dir").and_then(Value::as_str) {
        PathBuf::from(out_dir_str)
    } else {
        in_p.parent().map(|p| p.to_path_buf()).unwrap_or_else(|| PathBuf::from("."))
    };
    let ext = in_p.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
    let is_image = matches!(ext.as_str(), "png" | "jpg" | "jpeg" | "bmp" | "webp");
    if is_image {
        // ==================== 1. 单张图片 / 复杂单据全模态排版流水线 ====================
        tracing::info!("🖼️ [多模态总成] 命中单图排版通道, 启动 5 大模型底座全景重构: {:?}", in_p);
        let _permit = vram_guard.acquire(TaskWeight::Medium).await?;
        tokio::task::spawn_blocking(move || -> Result<Value, String> {
            let t0 = Instant::now();
            let dyn_img = image::open(&in_p).map_err(|e| format!("打开图像失败: {e}"))?;
            // 调起统一排版大脑
            let mut engine = DocParseEngine::default_engine();
            let (_doc_ast, markdown) = engine.parse_image_ast(&dyn_img, 0)
                .map_err(|e| format!("多模态图像重构推导失败: {e}"))?;
            // 将生成的完整 Markdown 写入输出目录
            let stem = in_p.file_stem().and_then(|s| s.to_str()).unwrap_or("parsed_image");
            let output_md_path = target_out_dir.join(format!("{}_parsed.md", stem));
            let _ = std::fs::create_dir_all(&target_out_dir);
            std::fs::write(&output_md_path, &markdown)
                .map_err(|e| format!("保存 Markdown 文件失败: {e}"))?;
            let elapsed_ms = t0.elapsed().as_secs_f64() * 1000.0;
            tracing::info!("✅ [多模态总成] 图像全量排版完成, 耗时: {:.2}ms, 产物: {:?}", elapsed_ms, output_md_path);
            Ok(json!({
                "success": true,
                "markdown": markdown,
                "output_md_path": output_md_path.to_string_lossy(),
                "task_out_dir": target_out_dir.to_string_lossy(),
                "images_dir": target_out_dir.join("images").to_string_lossy(),
                "route_label": "🧠 全血单图多模态重构轨 (Layout + SLANet + Formula + OCR + XY-Cut)",
                "elapsed_ms": elapsed_ms
            }))
        })
        .await
        .map_err(|e| format!("Tokio 线程调度异常: {e}"))?
    } else {
        // ==================== 2. PDF 多页文档双轨重构流水线 ====================
        tracing::info!("📄 [多模态总成] 命中 PDF 重构通道, 调起双轨漏斗引擎: {:?}", in_p);
        let res = PdfParseService::run_parse(
            file_path_str,
            &target_out_dir,
            Some(&vram_guard),
            None::<fn(usize, usize, &str)>,
        )
        .await
        .map_err(|e| format!("多模态 PDF 深度重构失败: {e}"))?;
        Ok(json!({
            "success": res.success,
            "markdown": res.markdown,
            "output_md_path": res.output_md_path,
            "task_out_dir": res.task_out_dir,
            "images_dir": res.images_dir,
            "route_label": res.route_label,
            "elapsed_ms": res.elapsed_ms
        }))
    }
}// 🛡️ service-formula 数学公式与 LaTeX 视觉提取专属处理器 (handlers/formula.rs)
