/// 计算 BBox8 四边形的外接轴对齐矩形 (AABB)
fn get_bbox8_aabb(b: &BBox8) -> (f32, f32, f32, f32) {
    let xs = [b[0], b[2], b[4], b[6]];
    let ys = [b[1], b[3], b[5], b[7]];
    let min_x = xs.iter().cloned().fold(f32::INFINITY, f32::min);
    let max_x = xs.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
    let min_y = ys.iter().cloned().fold(f32::INFINITY, f32::min);
    let max_y = ys.iter().cloned().fold(f32::NEG_INFINITY, f32::max);
    (min_x, min_y, max_x, max_y)
}
pub async fn handle(
    _tool_name: &str,
    params: Value,
    vram_guard: Arc<VramTokenGuard>,
) -> Result<Value, String> {
    let img_path_str = params.get("image_path").and_then(Value::as_str).ok_or("缺少 image_path 参数")?;
    let img_p = PathBuf::from(img_path_str);
    if !img_p.exists() { return Err(format!("表格图像文件不存在: {img_path_str}")); }
    let model_path = resolve_table_model_path()
        .ok_or_else(|| "未找到 SLANet 表格模型 (SLANet_plus.onnx / slanet.onnx)".to_string())?;
    let dict_path = resolve_table_dict_path()
        .ok_or_else(|| "未找到 SLANet 表格字典 (table_structure_dict.txt)".to_string())?;
    let _permit = vram_guard.acquire(TaskWeight::Light).await?;
    tokio::task::spawn_blocking(move || -> Result<Value, String> {
        let t0 = Instant::now();
        // 1. 读取原图
        let dynamic_img = image::open(&img_p).map_err(|e| format!("读取表格图片失败: {e}"))?;
        let rgb_img = dynamic_img.to_rgb8();
        // 2. SLANet 提取表格拓扑结构与单元格坐标
        let table_res = recognize_table_crop(&rgb_img, &model_path, &dict_path, None)
            .map_err(|e| format!("SLANet 神经推导失败: {e}"))?;
        // 3. PP-OCRv6 提取图像内所有文本行与几何中心
        let mut ocr_engine = OcrService::default_engine().map_err(|e| format!("加载 OCR 引擎失败: {e}"))?;
        let ocr_regions = ocr_engine.process_image(dynamic_img).map_err(|e| format!("OCR 推理失败: {e}"))?;
        // 预先计算各 OCR 文本块的几何中心 (cx, cy)
        let ocr_items: Vec<(f32, f32, String)> = ocr_regions
            .into_iter()
            .filter(|r| r.score >= 0.3 && !r.text.trim().is_empty())
            .map(|r| {
                let n = r.bbox.points.len() as f32;
                let sum_x: f32 = r.bbox.points.iter().map(|p| p.x).sum();
                let sum_y: f32 = r.bbox.points.iter().map(|p| p.y).sum();
                (sum_x / n.max(1.0), sum_y / n.max(1.0), r.text.trim().to_string())
            })
            .collect();
        // 4. 2D 几何空间包容性缝合：为每个 SLANet Cell 搜寻命中的 OCR 文字
        let padding = 3.0f32; // 容差像素缓冲
        let mut filled_texts: Vec<Option<String>> = Vec::with_capacity(table_res.cells.len());
        for cell in &table_res.cells {
            let (min_x, min_y, max_x, max_y) = get_bbox8_aabb(&cell.bbox);
            let mut matched_lines = Vec::new();
            for (cx, cy, text) in &ocr_items {
                if *cx >= (min_x - padding)
                    && *cx <= (max_x + padding)
                    && *cy >= (min_y - padding)
                    && *cy <= (max_y + padding)
                {
                    matched_lines.push((*cy, text.clone()));
                }
            }
            if matched_lines.is_empty() {
                filled_texts.push(None);
            } else {
                // 按纵向 y 坐标从上至下排序合并
                matched_lines.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
                let combined = matched_lines.into_iter().map(|(_, t)| t).collect::<Vec<_>>().join(" ");
                filled_texts.push(Some(combined));
            }
        }
        // 5. 组装饱满的 HTML 表格代码
        let html_structure = wrap_table_html_with_content(&table_res.structure_tokens, &filled_texts);
        let elapsed_ms = t0.elapsed().as_secs_f64() * 1000.0;
        Ok(json!({
            "image_path": img_p.to_string_lossy(),
            "total_cells": table_res.cells.len(),
            "html_structure": html_structure,
            "score": table_res.score,
            "cells": table_res.cells,
            "filled_count": filled_texts.iter().filter(|t| t.is_some()).count(),
            "elapsed_ms": elapsed_ms
        }))
    })
    .await
    .map_err(|e| format!("Tokio 线程调度异常: {e}"))?
}// 🛡️ service-translation Hy-MT2 38 语种神经机器翻译专属处理器 (handlers/translation.rs)
use serde_json::{json, Value};
use service_translation::{PureTranslationRequest, TranslationService};
use shared_contracts::{TaskWeight, VramTokenGuard};
use std::sync::Arc;
pub async fn handle(
    _tool_name: &str,
    params: Value,
    vram_guard: Arc<VramTokenGuard>,
) -> Result<Value, String> {
    // 智能兼顾单句字符串与多句数组输入
    let texts: Vec<String> = if let Some(arr) = params.get("texts").and_then(Value::as_array) {
        arr.iter().filter_map(Value::as_str).map(str::to_string).collect()
    } else if let Some(single_text) = params.get("text").and_then(Value::as_str) {
        vec![single_text.to_string()]
    } else {
        return Err("缺少待翻译文本参数 (texts 或 text)".into());
    };
    if texts.is_empty() {
        return Err("待翻译文本列表不能为空".into());
    }
    let target_lang_str = params.get("target_lang")
        .and_then(Value::as_str)
        .unwrap_or("Chinese")
        .to_string();
    let _permit = vram_guard.acquire(TaskWeight::Light).await?;
    let req = PureTranslationRequest {
        texts,
        target_lang: Some(target_lang_str.clone()),
    };
    let trans_res = TranslationService::run_translation_pipeline_with_progress(req, None).await
        .map_err(|e| format!("Hy-MT2 神经翻译推导失败: {e}"))?;
    Ok(json!({
        "total_segments": trans_res.translations.len(),
        "target_lang": target_lang_str,
        "translations": trans_res.translations,
        "elapsed_ms": trans_res.elapsed_ms
    }))
}// 🛡️ service-upscale 4K/8K 图像无损超分专属处理器 (handlers/vision.rs)
use serde_json::Value;
use service_upscale::{UpscaleService, UpscaleTask};
use shared_contracts::VramTokenGuard;
use std::path::Path;
use std::sync::Arc;
pub async fn handle(
    _tool_name: &str,
    params: Value,
    vram_guard: Arc<VramTokenGuard>,
) -> Result<Value, String> {
    let input_path_str = params.get("input_path").and_then(Value::as_str).ok_or("缺少 input_path 参数")?;
    let in_p = Path::new(input_path_str);
    if !in_p.exists() {
        return Err(format!("输入图像文件不存在: {input_path_str}"));
    }
    let target_scale = params.get("target_scale").and_then(Value::as_f64).map(|v| v as f32).unwrap_or(4.0);
    let max_output_side = params.get("max_output_side").and_then(Value::as_u64).map(|v| v as u32).unwrap_or(3840);
    let tile_size = params.get("tile_size").and_then(Value::as_u64).map(|v| v as u32);
    let tile_pad = params.get("tile_pad").and_then(Value::as_u64).map(|v| v as u32);
    let output_path_str = params.get("output_path").and_then(Value::as_str).map(str::to_string).unwrap_or_else(|| {
        let parent = in_p.parent().unwrap_or_else(|| Path::new("."));
        let stem = in_p.file_stem().and_then(|s| s.to_str()).unwrap_or("image");
        let ext = in_p.extension().and_then(|s| s.to_str()).unwrap_or("png");
        parent.join(format!("{}_upscaled_{:.0}x.{}", stem, target_scale, ext)).to_string_lossy().to_string()
    });
    let model_path = params.get("model_path").and_then(Value::as_str).map(str::to_string);
    let task = UpscaleTask {
        input_path: input_path_str.to_string(),
        output_path: output_path_str,
        model_path,
        target_scale: Some(target_scale),
        max_output_side: Some(max_output_side),
        tile_size,
        tile_pad,
    };
    let res = UpscaleService::run_upscale(&task, Some(&vram_guard), None::<fn(usize, usize, &str)>).await
        .map_err(|e| format!("RealESRGAN 超分推导失败: {e}"))?;
    Ok(serde_json::to_value(res).map_err(|e| e.to_string())?)
}// 🛡️ 纯血 Pi 官方 RPC 协议精准解构中枢 (bridge.rs)
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use shared_contracts::VramTokenGuard;
use std::path::{Path, PathBuf};
use std::process::Stdio;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use thiserror::Error;
use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader};
use tokio::process::{Child, ChildStdin, ChildStdout, Command};
use tokio::sync::{mpsc, Mutex};
#[derive(Debug, Error)]
pub enum AgentBridgeError {
    #[error("找不到 pi.exe 可执行文件: {0:?}")]
    PiNotFound(PathBuf),
    #[error("子进程启动失败: {0}")]
    ProcessSpawnFailed(#[from] std::io::Error),
    #[error("Stdio 通信管道已断开: {0}")]
    PipeBroken(String),
    #[error("JSON-RPC 序列化/反序列化失败: {0}")]
    JsonError(#[from] serde_json::Error),
}
pub type AgentResult<T> = Result<T, AgentBridgeError>;
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", content = "payload")]
pub enum AgentEvent {
    ThinkingDelta(String),
    ContentDelta(String),
    ToolCallStarted { tool_name: String, call_id: String, input: Value },
    ToolCallFinished { tool_name: String, call_id: String, result: Value },
    TurnFinished { total_tokens: Option<usize>, elapsed_ms: u64 },
    Error(String),
}
pub struct AgentBridge {
    stdin: Arc<Mutex<ChildStdin>>,
    cancel_token: Arc<AtomicBool>,
    _vram_guard: Arc<VramTokenGuard>,
    _child: Arc<Mutex<Child>>,
}
impl AgentBridge {
    pub fn resolve_pi_executable() -> Option<PathBuf> {
        let candidates = [
            PathBuf::from(r"C:\dev\ai-forge\src-tauri\bin\pi.exe"),
            PathBuf::from(r"src-tauri\bin\pi.exe"),
            PathBuf::from(r"bin\pi.exe"),
            PathBuf::from(r"C:\dev\bin\pi.exe"),
        ];
        if let Ok(current_exe) = std::env::current_exe() {
            if let Some(parent) = current_exe.parent() {
                let p1 = parent.join("pi.exe");
                let p2 = parent.join("bin").join("pi.exe");
                if p1.exists() { return Some(p1); }
                if p2.exists() { return Some(p2); }
            }
        }
        candidates.into_iter().find(|p| p.exists())
    }
    pub async fn spawn(
        vram_guard: Arc<VramTokenGuard>,
        extension_path: Option<&Path>,
        working_dir: Option<&Path>,
    ) -> AgentResult<(Self, mpsc::Receiver<AgentEvent>)> {
        let pi_bin = Self::resolve_pi_executable()
            .ok_or_else(|| AgentBridgeError::PiNotFound(PathBuf::from("pi.exe")))?;
        tracing::info!("🚀 [AgentBridge] 正在拉起 Pi 官方 RPC 引擎: {:?}", pi_bin);
        let mut cmd = Command::new(&pi_bin);
        cmd.arg("--mode").arg("rpc")
            .arg("--provider").arg("local")
            .arg("--model").arg("Qwen3-8B-LoRA-abliteration-IQ3_XXS")
            .arg("--approve")
            .arg("--no-session");
        if let Some(ext) = extension_path {
            if ext.exists() {
                cmd.arg("-e").arg(ext);
            }
        }
        if let Some(cwd) = working_dir {
            cmd.current_dir(cwd);
        }
        cmd.stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        #[cfg(target_os = "windows")]
        {
            cmd.creation_flags(0x08000000); // 静默运行 CREATE_NO_WINDOW
        }
        let mut child = cmd.spawn().map_err(AgentBridgeError::ProcessSpawnFailed)?;
        let child_pid = child.id();
        crate::agent::process_guardian::protect_child_pid(child_pid);
        let stdin = child.stdin.take().ok_or_else(|| AgentBridgeError::PipeBroken("获取 stdin 失败".into()))?;
        let stdout = child.stdout.take().ok_or_else(|| AgentBridgeError::PipeBroken("获取 stdout 失败".into()))?;
        let (event_tx, event_rx) = mpsc::channel::<AgentEvent>(256);
        let cancel_token = Arc::new(AtomicBool::new(false));
        let cancel_token_clone = cancel_token.clone();
        tokio::spawn(async move {
            Self::event_pump(stdout, event_tx, cancel_token_clone).await;
        });
        let bridge = Self {
            stdin: Arc::new(Mutex::new(stdin)),
            cancel_token,
            _vram_guard: vram_guard,
            _child: Arc::new(Mutex::new(child)),
        };
        Ok((bridge, event_rx))
    }
    pub async fn send_prompt(&self, prompt: &str, _session_id: Option<&str>) -> AgentResult<()> {
        self.cancel_token.store(false, Ordering::SeqCst);
        let req = json!({
            "type": "prompt",
            "id": format!("req_{}", std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis()),
            "message": prompt
        });
        let mut payload = serde_json::to_string(&req)?;
        payload.push('\n');
        let mut stdin = self.stdin.lock().await;
        stdin.write_all(payload.as_bytes()).await.map_err(|e| AgentBridgeError::PipeBroken(e.to_string()))?;
        stdin.flush().await.map_err(|e| AgentBridgeError::PipeBroken(e.to_string()))?;
        Ok(())
    }
    pub async fn abort(&self) -> AgentResult<()> {
        self.cancel_token.store(true, Ordering::SeqCst);
        let req = json!({
            "type": "abort",
            "id": "abort_current"
        });
        let mut payload = serde_json::to_string(&req)?;
        payload.push('\n');
        let mut stdin = self.stdin.lock().await;
        let _ = stdin.write_all(payload.as_bytes()).await;
        let _ = stdin.flush().await;
        Ok(())
    }
    /// 规整工具返回的真实业务载荷（兼容 details / data 嵌套）
    fn normalize_tool_result(raw: &Value) -> Value {
        if let Some(details) = raw.get("details") {
            if details.is_object() && !details.as_object().unwrap().is_empty() {
                return details.clone();
            }
        }
        if let Some(data) = raw.get("data") {
            if data.is_object() {
                return data.clone();
            }
        }
        raw.clone()
    }
    async fn event_pump(
        stdout: ChildStdout,
        tx: mpsc::Sender<AgentEvent>,
        cancel_token: Arc<AtomicBool>,
    ) {
        let reader = BufReader::new(stdout);
        let mut lines = reader.lines();
        let start_time = std::time::Instant::now();
        while let Ok(Some(line)) = lines.next_line().await {
            if cancel_token.load(Ordering::Relaxed) {
                let _ = tx.send(AgentEvent::Error("任务已终止".into())).await;
                break;
            }
            let trimmed = line.trim();
            if trimmed.is_empty() { continue; }
            if let Ok(val) = serde_json::from_str::<Value>(trimmed) {
                if let Some(msg_type) = val.get("type").and_then(Value::as_str) {
                    match msg_type {
                        // 1. 实时流式增量提取
                        "message_update" => {
                            if let Some(ev) = val.get("event") {
                                if let Some(ev_type) = ev.get("type").and_then(Value::as_str) {
                                    match ev_type {
                                        "thinking_delta" => {
                                            if let Some(delta) = ev.get("delta").and_then(Value::as_str) {
                                                let _ = tx.send(AgentEvent::ThinkingDelta(delta.to_string())).await;
                                            }
                                        }
                                        "text_delta" => {
                                            if let Some(delta) = ev.get("delta").and_then(Value::as_str) {
                                                let _ = tx.send(AgentEvent::ContentDelta(delta.to_string())).await;
                                            }
                                        }
                                        "tool_result" => {
                                            let call_id = ev.get("toolCallId").or_else(|| ev.get("id")).and_then(Value::as_str).unwrap_or("");
                                            let tool_name = ev.get("toolName").or_else(|| ev.get("name")).and_then(Value::as_str).unwrap_or("tool");
                                            let raw_res = ev.get("result").unwrap_or(&Value::Null);
                                            let normalized = Self::normalize_tool_result(raw_res);
                                            tracing::info!("✅ [AgentBridge] 收到 message_update.tool_result -> call_id: {}, 算子: {}", call_id, tool_name);
                                            let _ = tx.send(AgentEvent::ToolCallFinished {
                                                tool_name: tool_name.to_string(),
                                                call_id: call_id.to_string(),
                                                result: normalized,
                                            }).await;
                                        }
                                        _ => {}
                                    }
                                }
                            }
                        }
                        // 2. 工具调用启动
                        "tool_execution_start" | "tool_call" => {
                            let tool_name = val.get("toolName").or_else(|| val.get("name")).and_then(Value::as_str).unwrap_or("tool");
                            let call_id = val.get("toolCallId").or_else(|| val.get("id")).and_then(Value::as_str).unwrap_or("");
                            let input = val.get("input").or_else(|| val.get("arguments")).cloned().unwrap_or(json!({}));
                            tracing::info!("⚡ [AgentBridge] 工具执行开始 -> 算子: {}, call_id: {}", tool_name, call_id);
                            let _ = tx.send(AgentEvent::ToolCallStarted {
                                tool_name: tool_name.to_string(),
                                call_id: call_id.to_string(),
                                input,
                            }).await;
                        }
                        // 3. 工具调用完成
                        "tool_execution_end" => {
                            let tool_name = val.get("toolName").or_else(|| val.get("name")).and_then(Value::as_str).unwrap_or("tool");
                            let call_id = val.get("toolCallId").or_else(|| val.get("id")).and_then(Value::as_str).unwrap_or("");
                            let raw_res = val.get("result").unwrap_or(&Value::Null);
                            let normalized = Self::normalize_tool_result(raw_res);
                            tracing::info!("✅ [AgentBridge] 工具执行完成 -> 算子: {}, call_id: {}", tool_name, call_id);
                            let _ = tx.send(AgentEvent::ToolCallFinished {
                                tool_name: tool_name.to_string(),
                                call_id: call_id.to_string(),
                                result: normalized,
                            }).await;
                        }
                        // 4. 回合收敛完成报文
                        "agent_end" | "turn_finish" => {
                            if let Some(msgs) = val.get("messages").and_then(Value::as_array) {
                                for msg in msgs {
                                    if msg.get("role").and_then(Value::as_str) == Some("assistant") {
                                        if let Some(contents) = msg.get("content").and_then(Value::as_array) {
                                            for item in contents {
                                                let c_type = item.get("type").and_then(Value::as_str).unwrap_or("");
                                                if c_type == "thinking" {
                                                    if let Some(th) = item.get("thinking").and_then(Value::as_str) {
                                                        let _ = tx.send(AgentEvent::ThinkingDelta(th.to_string())).await;
                                                    }
                                                } else if c_type == "text" {
                                                    if let Some(txt) = item.get("text").and_then(Value::as_str) {
                                                        let _ = tx.send(AgentEvent::ContentDelta(txt.to_string())).await;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            let elapsed = start_time.elapsed().as_millis() as u64;
                            tracing::info!("🏁 [AgentBridge] 本轮回合执行完成, 耗时: {} ms", elapsed);
                            let _ = tx.send(AgentEvent::TurnFinished {
                                total_tokens: None,
                                elapsed_ms: elapsed,
                            }).await;
                        }
                        _ => {}
                    }
                }
            }
        }
    }
}// 🛡️ 极简统一算子路由器 (dispatcher.rs)
use super::handlers;
use serde_json::Value;
use shared_contracts::VramTokenGuard;
use std::sync::Arc;
pub async fn dispatch(
    tool_name: &str,
    params: Value,
    vram_guard: Arc<VramTokenGuard>,
) -> Result<Value, String> {
    tracing::info!("⚡ [原子总线分发] 目标算子: {} | 显存余量: {} MB", tool_name, vram_guard.available_vram_mb());
    match tool_name {
        // 1. PDF 物理几何与位图
        "pdf_get_meta" | "pdf_render_page_image" | "pdf_extract_char_boxes" | "pdf_extract_raw_text" => {
            handlers::pdf::handle(tool_name, params, vram_guard).await
        }
        // 2. 版面分析与阅读序
        "layout_detect_regions" => {
            handlers::layout::handle(tool_name, params, vram_guard).await
        }
        // 3. OCR 文字与坐标提取
        "ocr_recognize_image" | "native_ocr_recognize" => {
            handlers::ocr::handle(tool_name, params, vram_guard).await
        }
        // 4. 数学公式与 LaTeX 重构
        "formula_recognize_latex" => {
            handlers::formula::handle(tool_name, params, vram_guard).await
        }
        // 5. 复杂表格拓扑与 HTML 重构
        "table_recognize_structure" => {
            handlers::table::handle(tool_name, params, vram_guard).await
        }
        // 6. 视觉超分
        "native_upscale_image" => {
            handlers::vision::handle(tool_name, params, vram_guard).await
        }
        // 7. 语音识别
        "native_asr_transcribe" => {
            handlers::audio::handle(tool_name, params, vram_guard).await
        }
        // 8. 神经翻译
        "native_neural_translate" => {
            handlers::translation::handle(tool_name, params, vram_guard).await
        }
        // 9. 格式转换
        "native_format_convert" => {
            handlers::converter::handle(tool_name, params, vram_guard).await
        }
        // 10. 多模态文档复合流水线
        "native_doc_parse" => {
            handlers::doc::handle(tool_name, params, vram_guard).await
        }
        _ => Err(format!("未知的原子底座算子: {tool_name}")),
    }
}// 🛡️ 紫电 AI - 本地大模型推理基座后台守护服务 (llm_server.rs)
